import{_ as o,C as n,o as s,c as l,a2 as i,E as c,j as t,a as e}from"./chunks/framework.CBxkvBm_.js";const x=JSON.parse('{"title":"Automatic Differentiation & Relaxations","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/autodiff.md","filePath":"algorithms/autodiff.md"}'),d={name:"algorithms/autodiff.md"};function m(p,a,u,h,g,f){const r=n("MermaidBlock");return s(),l("div",null,[a[0]||(a[0]=i('<h1 id="automatic-differentiation-relaxations" tabindex="-1">Automatic Differentiation &amp; Relaxations <a class="header-anchor" href="#automatic-differentiation-relaxations" aria-label="Permalink to &quot;Automatic Differentiation &amp; Relaxations&quot;">​</a></h1><p><strong>Implementation</strong>:</p><ul><li>Forward Mode: <code>Dual</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/autodiff/dual.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/autodiff/dual.ts</code></a></li><li>Reverse Mode: <code>AdTape</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/autodiff/tape.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/autodiff/tape.ts</code></a></li><li>Sparse Jacobian Coloring: <code>CCSMatrix</code> &amp; <code>ColoringEngine</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/autodiff/coloring.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/autodiff/coloring.ts</code></a></li><li>McCormick Envelopes: <code>McCormickTuple</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/autodiff/mccormick.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/autodiff/mccormick.ts</code></a></li><li>Affine Arithmetic: <code>AffineForm</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/autodiff/affine.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/autodiff/affine.ts</code></a></li><li>Hybrid Adjoint Sensitivity &amp; Saltation Matrices: <code>HybridAdjointSolver</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/simulate/src/core/hybrid-adjoint.ts" target="_blank" rel="noreferrer"><code>packages/simulate/src/core/hybrid-adjoint.ts</code></a></li><li>Aitken Dynamic $\\Delta$-Relaxation &amp; Multi-Rate Sub-Cycling: <code>VectorAitkenRelaxation</code> &amp; <code>MultiRateSubCycleScheduler</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/simulate/src/core/fsi-relaxation.ts" target="_blank" rel="noreferrer"><code>packages/simulate/src/core/fsi-relaxation.ts</code></a></li></ul><hr><h2 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h2><h3 id="forward-mode-dual-numbers" tabindex="-1">Forward-Mode Dual Numbers <a class="header-anchor" href="#forward-mode-dual-numbers" aria-label="Permalink to &quot;Forward-Mode Dual Numbers&quot;">​</a></h3><ul><li><strong>Clifford, W. K. (1873)</strong>. <em>&quot;Preliminary sketch of biquaternions.&quot;</em><br><strong>Proceedings of the London Mathematical Society</strong>, 4, pp. 381–395.<br> DOI: <a href="https://doi.org/10.1112/plms/s1-4.1.381" target="_blank" rel="noreferrer">10.1112/plms/s1-4.1.381</a></li><li><strong>Study, E. (1903)</strong>. <em>Geometrie der Dynamen: Die Zusammensetzung von Kräften und verwandte Gegenstände der Geometrie.</em> B.G. Teubner.</li><li><strong>Rall, L. B. (1981)</strong>. <em>Automatic Differentiation: Techniques and Applications.</em><br><strong>Lecture Notes in Computer Science</strong>, 120, Springer.<br> DOI: <a href="https://doi.org/10.1007/3-540-10861-0" target="_blank" rel="noreferrer">10.1007/3-540-10861-0</a></li></ul><h3 id="reverse-mode-adjoint-accumulation-wengert-list" tabindex="-1">Reverse-Mode Adjoint Accumulation (Wengert List) <a class="header-anchor" href="#reverse-mode-adjoint-accumulation-wengert-list" aria-label="Permalink to &quot;Reverse-Mode Adjoint Accumulation (Wengert List)&quot;">​</a></h3><ul><li><strong>Wengert, R. E. (1964)</strong>. <em>&quot;A simple automatic derivative evaluation program.&quot;</em><br><strong>Communications of the ACM</strong>, 7(8), pp. 463–464.<br> DOI: <a href="https://doi.org/10.1145/355586.364791" target="_blank" rel="noreferrer">10.1145/355586.364791</a></li><li><strong>Linnainmaa, S. (1976)</strong>. <em>&quot;Taylor expansion of the accumulated rounding error.&quot;</em><br><strong>BIT Numerical Mathematics</strong>, 16(2), pp. 146–160.<br> DOI: <a href="https://doi.org/10.1007/BF01931367" target="_blank" rel="noreferrer">10.1007/BF01931367</a></li><li><strong>Griewank, A., &amp; Walther, A. (2008)</strong>. <em>Evaluating Derivatives: Principles and Techniques of Algorithmic Differentiation</em> (2nd ed.). SIAM.<br> ISBN: <a href="https://epubs.siam.org/doi/book/10.1137/1.9780898717761" target="_blank" rel="noreferrer">978-0-898716-59-7</a></li></ul><h3 id="distance-2-graph-coloring-for-sparse-jacobians" tabindex="-1">Distance-2 Graph Coloring for Sparse Jacobians <a class="header-anchor" href="#distance-2-graph-coloring-for-sparse-jacobians" aria-label="Permalink to &quot;Distance-2 Graph Coloring for Sparse Jacobians&quot;">​</a></h3><ul><li><strong>Curtis, A. R., Powell, M. J. D., &amp; Reid, J. K. (1974)</strong>. <em>&quot;On the estimation of sparse Jacobian matrices.&quot;</em><br><strong>Journal of the Institute of Mathematics and Its Applications</strong>, 13(1), pp. 117–119.<br> DOI: <a href="https://doi.org/10.1093/imamat/13.1.117" target="_blank" rel="noreferrer">10.1093/imamat/13.1.117</a> <em>(CPR Algorithm)</em></li><li><strong>Coleman, T. F., &amp; Moré, J. J. (1983)</strong>. <em>&quot;Estimation of sparse Jacobian matrices and graph coloring problems.&quot;</em><br><strong>SIAM Journal on Numerical Analysis</strong>, 20(1), pp. 187–209.<br> DOI: <a href="https://doi.org/10.1137/0720013" target="_blank" rel="noreferrer">10.1137/0720013</a></li><li><strong>Gebremedhin, A. H., Manne, F., &amp; Pothen, A. (2005)</strong>. <em>&quot;What color is your Jacobian? Graph coloring for computing derivatives.&quot;</em><br><strong>SIAM Review</strong>, 47(4), pp. 629–705.<br> DOI: <a href="https://doi.org/10.1137/S0036144504446096" target="_blank" rel="noreferrer">10.1137/S0036144504446096</a></li></ul><h3 id="mccormick-relaxations-affine-arithmetic" tabindex="-1">McCormick Relaxations &amp; Affine Arithmetic <a class="header-anchor" href="#mccormick-relaxations-affine-arithmetic" aria-label="Permalink to &quot;McCormick Relaxations &amp; Affine Arithmetic&quot;">​</a></h3><ul><li><strong>McCormick, G. P. (1976)</strong>. <em>&quot;Computability of global solutions to factorable nonconvex programs: Part I—Convex underestimating problems.&quot;</em><br><strong>Mathematical Programming</strong>, 10(1), pp. 147–175.<br> DOI: <a href="https://doi.org/10.1007/BF01580665" target="_blank" rel="noreferrer">10.1007/BF01580665</a></li><li><strong>Mitsos, A., Chachuat, B., &amp; Barton, P. I. (2009)</strong>. <em>&quot;McCormick-based relaxations of algorithms.&quot;</em><br><strong>SIAM Journal on Optimization</strong>, 20(2), pp. 573–601.<br> DOI: <a href="https://doi.org/10.1137/080717341" target="_blank" rel="noreferrer">10.1137/080717341</a></li><li><strong>Tsoukalas, A., &amp; Mitsos, A. (2014)</strong>. <em>&quot;Multivariate McCormick relaxations.&quot;</em><br><strong>Journal of Global Optimization</strong>, 59(2), pp. 633–662.<br> DOI: <a href="https://doi.org/10.1007/s10898-014-0169-z" target="_blank" rel="noreferrer">10.1007/s10898-014-0169-z</a></li><li><strong>de Figueiredo, L. H., &amp; Stolfi, J. (2004)</strong>. <em>&quot;Affine arithmetic: concepts and applications.&quot;</em><br><strong>Numerical Algorithms</strong>, 37(1), pp. 147–158.<br> DOI: <a href="https://doi.org/10.1023/B:NUMA.0000049462.70970.b6" target="_blank" rel="noreferrer">10.1023/B:NUMA.0000049462.70970.b6</a></li></ul><h3 id="hybrid-adjoint-sensitivity-saltation-matrices" tabindex="-1">Hybrid Adjoint Sensitivity &amp; Saltation Matrices <a class="header-anchor" href="#hybrid-adjoint-sensitivity-saltation-matrices" aria-label="Permalink to &quot;Hybrid Adjoint Sensitivity &amp; Saltation Matrices&quot;">​</a></h3><ul><li><strong>Barton, P. I., &amp; Lee, C. K. (2002)</strong>. <em>&quot;Modeling, simulation, sensitivity analysis, and optimization of hybrid systems.&quot;</em><br><strong>ACM Transactions on Modeling and Computer Simulation</strong>, 12(4), pp. 256–289.<br> DOI: <a href="https://doi.org/10.1145/643120.643122" target="_blank" rel="noreferrer">10.1145/643120.643122</a></li><li><strong>Filippov, A. F. (1988)</strong>. <em>Differential Equations with Discontinuous Righthand Sides.</em><br><strong>Mathematics and Its Applications</strong>, 18, Springer.<br> DOI: <a href="https://doi.org/10.1007/978-94-015-7793-9" target="_blank" rel="noreferrer">10.1007/978-94-015-7793-9</a></li><li><strong>Corner, S., Sandu, A., &amp; Sandu, C. (2019)</strong>. <em>&quot;Adjoint sensitivity analysis of hybrid multibody dynamical systems.&quot;</em><br><strong>Multibody System Dynamics</strong>, 49, pp. 395–420.<br> DOI: <a href="https://doi.org/10.1007/s11044-019-09725-2" target="_blank" rel="noreferrer">10.1007/s11044-019-09725-2</a></li></ul><h3 id="aitken-dynamic-delta-relaxation-for-partitioned-co-simulation" tabindex="-1">Aitken Dynamic $\\Delta$-Relaxation for Partitioned Co-Simulation <a class="header-anchor" href="#aitken-dynamic-delta-relaxation-for-partitioned-co-simulation" aria-label="Permalink to &quot;Aitken Dynamic $\\Delta$-Relaxation for Partitioned Co-Simulation&quot;">​</a></h3><ul><li><strong>Küttler, U., &amp; Wall, W. A. (2008)</strong>. <em>&quot;Fixed-point fluid–structure interaction solvers with dynamic relaxation.&quot;</em><br><strong>Computational Mechanics</strong>, 43(1), pp. 61–72.<br> DOI: <a href="https://doi.org/10.1007/s00466-008-0255-5" target="_blank" rel="noreferrer">10.1007/s00466-008-0255-5</a></li><li><strong>Irons, B. M., &amp; Tuck, R. C. (1969)</strong>. <em>&quot;A version of the Aitken accelerator for computer iteration.&quot;</em><br><strong>International Journal for Numerical Methods in Engineering</strong>, 1(3), pp. 275–277.<br> DOI: <a href="https://doi.org/10.1002/nme.1620010306" target="_blank" rel="noreferrer">10.1002/nme.1620010306</a></li></ul><hr><h2 id="modelscript-architectural-rationale" tabindex="-1">ModelScript Architectural Rationale <a class="header-anchor" href="#modelscript-architectural-rationale" aria-label="Permalink to &quot;ModelScript Architectural Rationale&quot;">​</a></h2><p>Numerical finite-difference approximations ($\\frac{f(x + h) - f(x)}{h}$) suffer from a fundamental trade-off: large step sizes $h$ cause truncation errors, while small step sizes cause catastrophic floating-point cancellation.</p><p>ModelScript implements an integrated suite of <strong>exact differentiation and continuous bounding engines</strong> inside WebAssembly linear memory:</p><ol><li><strong>Forward-Mode Dual Numbers</strong>: Computes exact machine-precision directional derivatives $\\nabla f(x) \\cdot v$ concurrently with primal function evaluation for Newton steps in algebraic loops and stiff ODE/DAE integrators without allocating expression trees.</li><li><strong>Reverse-Mode Computational Tape</strong>: Evaluates scalar objective gradients $\\nabla f(x) \\in \\mathbb{R}^N$ with cost proportional to $O(1)$ evaluations of $f$, enabling gradient-based parameter estimation and surrogate neural network training.</li><li><strong>CPR Distance-2 Graph Coloring</strong>: For large-scale DAE systems ($N = 10{,}000+$ equations), evaluating the full $N \\times N$ Jacobian naively requires $N$ forward passes. CPR distance-2 coloring partitions structural columns into $p \\ll N$ non-interfering groups (typically $p \\le 15$ for sparse physical networks), reducing Jacobian assembly time by orders of magnitude.</li><li><strong>McCormick Envelopes &amp; Affine Arithmetic</strong>: Classical interval arithmetic suffers from the <strong>dependency problem</strong>: evaluating $x - x$ for $x \\in [0, 1]$ yields $[-1, 1]$ instead of $0$, causing rapid exponential bounding blowup. Affine arithmetic tracks first-order noise symbols ($\\epsilon_i \\in [-1, 1]$) across state equations, while McCormick relaxations compute rigorous convex lower bounds ($f^R$) and concave upper bounds ($f^{AR}$) for non-convex global optimization.</li><li><strong>Hybrid Adjoint Sensitivity with Saltation Matrices</strong>: Standard continuous adjoint solvers break down across Modelica <code>when</code>/<code>reinit</code> events, impact mechanics, or switching surfaces because Dirac delta impulses arise at event-crossing times $t^*$. ModelScript propagates reverse-mode adjoints across non-smooth mode transitions using exact saltation matrix jump conditions alongside optional sigmoidal equation smoothing (<code>DAEEventRelaxer</code>).</li><li><strong>Aitken Dynamic $\\Delta$-Relaxation</strong>: Partitioned co-simulation of strongly coupled multi-physics domains (such as lightweight aerodynamic structures coupled to dense fluids or algebraic FMU loops) diverges under explicit Gauss-Seidel macro-steps due to the artificial added-mass effect. Dynamic vector Aitken acceleration stabilizes fixed-point iterations without requiring monolithic cross-FMU Jacobians.</li></ol><hr><h2 id="modelscript-modifications-wasm-architecture" tabindex="-1">ModelScript Modifications &amp; WASM Architecture <a class="header-anchor" href="#modelscript-modifications-wasm-architecture" aria-label="Permalink to &quot;ModelScript Modifications &amp; WASM Architecture&quot;">​</a></h2>',24)),c(r,{code:"flowchart%20TD%0A%20%20%20%20DAE%5B%22DAE%20Linear%20Arena%20Expressions%22%5D%20--%3E%20FORWARD%5B%22Dual%20Numbers%20(16-byte%20Unmanaged)%22%5D%0A%20%20%20%20DAE%20--%3E%20TAPE%5B%22Reverse%20Adjoint%20Tape%20(32-byte%20Nodes)%22%5D%0A%20%20%20%20DAE%20--%3E%20SPARSITY%5B%22Bipartite%20Sparsity%20Graph%22%5D%0A%20%20%20%20SPARSITY%20--%3E%20COLORING%5B%22CPR%20Distance-2%20Column%20Coloring%22%5D%0A%20%20%20%20COLORING%20--%3E%20COMPRESSED_JAC%5B%22Compressed%20Jacobian%20Seeds%3Cbr%2F%3Ep%20%3C%3C%20N%20Directional%20Passes%22%5D%0A%20%20%20%20FORWARD%20--%3E%20COMPRESSED_JAC%0A%20%20%20%20COMPRESSED_JAC%20--%3E%20NEWTON%5B%22WASM%20Newton-Raphson%20Solver%3Cbr%2F%3E(TR-BDF2%2C%20Rodas-4P%2C%20Tearing)%22%5D%0A%20%20%20%20DAE%20--%3E%20RELAX%5B%22McCormick%20Envelopes%20%26%20Affine%20Noise%20Form%22%5D%0A%20%20%20%20RELAX%20--%3E%20GLOBAL%5B%22Global%20Branch-and-Bound%20%26%20HC4%20Contractor%22%5D%0A%20%20%20%20DAE%20--%3E%20HYBRID_ADJ%5B%22HybridAdjointSolver%3Cbr%2F%3EHermite%20Checkpoint%20Tape%20%26%20Saltation%20Jumps%22%5D%0A%20%20%20%20DAE%20--%3E%20AITKEN%5B%22VectorAitkenRelaxation%3Cbr%2F%3ECoupled%20FSI%20%26%20FMU%20Macro-Step%20Convergence%22%5D%0A"}),a[1]||(a[1]=i('<h3 id="_1-zero-gc-dual-number-arithmetic" tabindex="-1">1. Zero-GC Dual Number Arithmetic <a class="header-anchor" href="#_1-zero-gc-dual-number-arithmetic" aria-label="Permalink to &quot;1. Zero-GC Dual Number Arithmetic&quot;">​</a></h3><p>Represented as a 16-byte unmanaged struct (<code>@unmanaged</code>) in WASM memory:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@unmanaged</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Dual</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  val</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> f64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Primal evaluation f(x)</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  dot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> f64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Directional derivative f&#39;(x) * v</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>All elementary operators ($+, -, \\times, /$) and transcendental functions ($\\sin, \\cos, \\exp, \\log, \\text{pow}$) are inlined without intermediate object allocation.</p><h3 id="_2-linear-memory-computational-tape" tabindex="-1">2. Linear Memory Computational Tape <a class="header-anchor" href="#_2-linear-memory-computational-tape" aria-label="Permalink to &quot;2. Linear Memory Computational Tape&quot;">​</a></h3><p>The reverse-mode tape records operations into a flat 32-byte stride unmanaged array: $$\\text{Stride: } [\\text{op: u32}, \\text{left: u32}, \\text{right: u32}, \\text{aux: u32}, \\text{valLo: u32}, \\text{valHi: u32}, \\text{gradLo: u32}, \\text{gradHi: u32}]$$ During the reverse pass, adjoints are accumulated in topological order directly in linear memory: $$\\bar{x}_j \\leftarrow \\bar{x}_j + \\bar{x}_i \\cdot \\frac{\\partial f_i}{\\partial x_j}$$</p><h3 id="_3-cpr-distance-2-coloring-algorithm" tabindex="-1">3. CPR Distance-2 Coloring Algorithm <a class="header-anchor" href="#_3-cpr-distance-2-coloring-algorithm" aria-label="Permalink to &quot;3. CPR Distance-2 Coloring Algorithm&quot;">​</a></h3><p>Two columns $j$ and $k$ in the Jacobian $J$ are <strong>structurally orthogonal</strong> if they do not share any non-zero row entry: $$\\text{Row}(j) \\cap \\text{Row}(k) = \\emptyset$$ The graph coloring algorithm:</p><ol><li>Constructs the bipartite graph $B = (V_R, V_C, E)$ where edge $(i, j) \\in E \\iff \\frac{\\partial f_i}{\\partial x_j} \\neq 0$.</li><li>Colors columns $V_C$ such that any pair of columns connected by a path of length 2 receives different colors.</li><li>Groups columns of color $c \\in {1, \\dots, p}$ into a perturbation vector $d^{(c)} = \\sum_{j \\in \\text{Color}(c)} e_j$.</li><li>Computes the entire compressed Jacobian in exactly $p$ directional forward-mode passes: $$J \\cdot d^{(c)} = \\sum_{j \\in \\text{Color}(c)} J_{*, j}$$</li></ol><h3 id="_4-mccormick-relaxations" tabindex="-1">4. McCormick Relaxations <a class="header-anchor" href="#_4-mccormick-relaxations" aria-label="Permalink to &quot;4. McCormick Relaxations&quot;">​</a></h3><p>For factorable bilinear products $z = x \\cdot y$ over bounds $x \\in [x^L, x^U]$ and $y \\in [y^L, y^U]$, the convex underestimator $z^{cv}$ and concave overestimator $z^{cc}$ are: $$z^{cv} = \\max\\left(x^L y + x y^L - x^L y^L, ; x^U y + x y^U - x^U y^U\\right)$$ $$z^{cc} = \\min\\left(x^U y + x y^L - x^U y^L, ; x^L y + x y^U - x^L y^U\\right)$$ ModelScript evaluates McCormick tuples $[z^{cv}, z^{cc}, \\nabla z^{cv}, \\nabla z^{cc}]$ directly on WASM arrays.</p><h3 id="_5-hybrid-adjoint-sensitivity-with-saltation-matrices-hybrid-adjoint-ts" tabindex="-1">5. Hybrid Adjoint Sensitivity with Saltation Matrices (<code>hybrid-adjoint.ts</code>) <a class="header-anchor" href="#_5-hybrid-adjoint-sensitivity-with-saltation-matrices-hybrid-adjoint-ts" aria-label="Permalink to &quot;5. Hybrid Adjoint Sensitivity with Saltation Matrices (`hybrid-adjoint.ts`)&quot;">​</a></h3><p>When a hybrid DAE trajectory crosses a discrete event surface $g(x(t^<em>), p) = 0$ with state reset map $x(t^{</em>+}) = h(x(t^{*-}), p)$ (such as Modelica <code>when</code> clauses, <code>reinit(x, expr)</code> impulses, or mechanical contact restitution), the forward sensitivity transition matrix undergoes a discontinuous rank-1 update governed by the <strong>saltation matrix</strong>: $$\\Xi = I + \\frac{\\left(f^+ - f^- - \\frac{\\partial h}{\\partial t}\\right) (\\nabla_x g)^T}{(\\nabla_x g)^T f^- + \\frac{\\partial g}{\\partial t}}$$</p><p><code>HybridAdjointSolver</code> (<code>solveHybridAdjoint</code> in <code>packages/simulate/src/core/hybrid-adjoint.ts</code>) implements a three-phase hybrid sensitivity pipeline:</p><ol><li><strong>Forward Integration &amp; Event Localization</strong>: Integrates the primal DAE arena while streaming cubic Hermite segments into <code>DenseHermiteCheckpointTape</code>. Whenever an event indicator $h(t, x, p)$ changes sign across a step, a 20-iteration bisection root-finder isolates the exact crossing time $t_e$, records pre-event limits $(x^-, \\dot{x}^-)$, applies the discrete reset map $x^+ = \\Delta(x^-, p)$, and re-evaluates post-event derivatives $(x^+, \\dot{x}^+)$.</li><li><strong>Adjoint Jump across Event Surfaces</strong>: During backward Heun integration of the co-state $\\lambda(t)$, crossing $t_e$ in reverse applies the transposed saltation jump condition to $\\lambda(t_e^-)$ and accumulates the discrete event timing contribution into the parameter gradient $\\frac{d\\mathcal{L}}{dp}$: $$\\lambda(t_e^-) = \\left[\\frac{\\partial \\Delta}{\\partial x}\\right]^T \\lambda(t_e^+) + \\frac{\\left(\\frac{d\\Delta}{dt}\\right)^- - \\dot{x}^+}{\\dot{h}^-} \\nabla_x h(t_e^-)$$ $$\\Delta\\left(\\frac{d\\mathcal{L}}{dp}\\right) = \\left[\\frac{\\partial \\Delta}{\\partial p}\\right]^T \\lambda(t_e^+) + \\frac{\\left(\\frac{d\\Delta}{dt}\\right)^- - \\dot{x}^+}{\\dot{h}^-} \\nabla_p h(t_e^-)$$</li><li><strong>Optional Sigmoidal Event Relaxation</strong>: For models with dense chattering or non-smooth algebraic switches (<code>if</code>, <code>abs</code>, <code>min</code>, <code>max</code>), <code>HybridAdjointSolver</code> optionally invokes <code>DAEEventRelaxer</code> to smooth C0 discontinuities into $C^\\infty$ sigmoidal transitions prior to adjoint integration.</li></ol><h3 id="_6-aitken-dynamic-delta-relaxation-for-coupled-co-simulation-fsi-relaxation-ts" tabindex="-1">6. Aitken Dynamic $\\Delta$-Relaxation for Coupled Co-Simulation (<code>fsi-relaxation.ts</code>) <a class="header-anchor" href="#_6-aitken-dynamic-delta-relaxation-for-coupled-co-simulation-fsi-relaxation-ts" aria-label="Permalink to &quot;6. Aitken Dynamic $\\Delta$-Relaxation for Coupled Co-Simulation (`fsi-relaxation.ts`)&quot;">​</a></h3><p>In partitioned Fluid-Structure Interaction (FSI) and multi-FMU co-simulation macro-steps, exchanging boundary loads and displacements via unrelaxed fixed-point iteration $x_{k+1} = \\tilde{x}(x_k)$ often diverges due to artificial added-mass instability.</p><p><code>VectorAitkenRelaxation</code> (<code>packages/simulate/src/core/fsi-relaxation.ts</code>) accelerates and stabilizes convergence over scalar variables, multi-DOF nodal displacement vectors, or 3D boundary traction maps (<code>relaxBoundaryLoads</code>):</p>',18)),a[2]||(a[2]=t("ol",null,[t("li",null,[t("strong",null,"Fixed-Point Residual"),e(": At macro-step sub-iteration $k$, computes the interface residual $r_k = \\tilde{x}"),t("em",{"k-1":""},"k - x"),e("$ and residual difference $\\Delta r_k = r_k - r_{k-1}$.")]),t("li",null,[t("strong",null,"Secant Aitken Factor Update"),e(": Updates the dynamic relaxation factor $\\omega_k$ via the multidimensional Aitken $\\Delta^2$ projection: $$\\omega_k = -\\omega_{k-1} \\frac{r_{k-1}^T (r_k - r_{k-1})}{|r_k - r_{k-1}|"),t("em",null,"2^2}$$ clamped to a safe stability interval $\\omega_k \\in [\\omega"),e("{\\min}, \\omega_{\\max}]$ (default $[0.02, 1.0]$).")]),t("li",null,[t("strong",null,"Relaxed State Update"),e(": Advances the interface state via under-relaxation: $$x_{k+1} = x_k + \\omega_k r_k$$ terminating when the relative residual norm $|r_k|_2 / (|x_k|_2 + \\epsilon) < \\text{tol}$.")]),t("li",null,[t("strong",null,[e("Multi-Rate Sub-Cycling ("),t("code",null,"MultiRateSubCycleScheduler"),e(")")]),e(": Synchronizes fast acoustic CFD steps ($\\Delta t_{\\text{CFD}} \\sim 10^{-4}\\text{ s}$), intermediate elastodynamic FEA steps ($\\Delta t_{\\text{FEA}} \\sim 10^{-3}\\text{ s}$), and macro 1D DAE steps ($\\Delta t_{\\text{macro}} \\sim 10^{-2}\\text{ s}$) using linear sub-step boundary interpolation $\\mathbf{u}(\\tau) = (1 - \\tau)\\mathbf{u}"),t("em",null,"{\\text{prev}} + \\tau \\mathbf{u}"),e("{\\text{target}}$.")])],-1)),a[3]||(a[3]=i('<hr><h2 id="upstream-downstream-integration" tabindex="-1">Upstream &amp; Downstream Integration <a class="header-anchor" href="#upstream-downstream-integration" aria-label="Permalink to &quot;Upstream &amp; Downstream Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Pipeline Component</th><th style="text-align:left;">Upstream Dependencies</th><th style="text-align:left;">Downstream Consumers</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Dual Numbers</strong></td><td style="text-align:left;"><code>DAEBuilder</code> AST, Variable seed vector</td><td style="text-align:left;">Algebraic loop tearing, Newton solvers, sensitivity analysis</td></tr><tr><td style="text-align:left;"><strong>AdTape</strong></td><td style="text-align:left;"><code>DAEBuilder</code> objective expressions</td><td style="text-align:left;">L-BFGS-B optimizer, surrogate loss backprop</td></tr><tr><td style="text-align:left;"><strong>CPR Coloring</strong></td><td style="text-align:left;">Bipartite incidence matrix from <code>BltEngine</code></td><td style="text-align:left;">Sparse Jacobian generation, SUNDIALS/TR-BDF2 linear solves</td></tr><tr><td style="text-align:left;"><strong>McCormick &amp; Affine</strong></td><td style="text-align:left;">Bound intervals from <code>QueryEngine</code></td><td style="text-align:left;">HC4 contractor, Nelson-Oppen theory coordinator, SOS bounds</td></tr><tr><td style="text-align:left;"><strong>HybridAdjointSolver</strong></td><td style="text-align:left;"><code>DAEBuilder</code>, <code>DenseHermiteCheckpointTape</code>, Events</td><td style="text-align:left;">Hybrid parameter calibration, optimal control across mode switches</td></tr><tr><td style="text-align:left;"><strong>VectorAitkenRelaxation</strong></td><td style="text-align:left;">Partitioned CFD/FEA boundary loads &amp; FMU ports</td><td style="text-align:left;">Coupled aeroelastic FSI solver, SSP co-simulation master</td></tr></tbody></table>',3))])}const k=o(d,[["render",m]]);export{x as __pageData,k as default};
